style.css:
/* Set background to pastel colors */
body {
    background-color: #f5f5f5; /* light gray for good contrast */
    color: #4a4a4a; /* dark gray text */
}

/* Links */
a {
    color: #b28bf7; /* pastel purple */
}

a:hover {
    color: #ffb7ce; /* pastel pink */
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: #b28bf7; /* pastel purple */
}

/* Code blocks */
code, pre {
    background-color: #e0f7fa; /* pastel mint green */
    color: #616161; /* dark gray for code */
    padding: 5px;
    border-radius: 5px;
}

/* Buttons */
button {
    background-color: #b28bf7; /* pastel purple */
    color: white;
    border: none;
    padding: 10px;
    border-radius: 5px;
}

button:hover {
    background-color: #ffb7ce; /* pastel pink */
}

/* Links in code */
a[href^="http"]:hover {
    color: #a7f1e1; /* pastel baby blue */
}
